// Throwaway structural sanity check for src/Dashboard.tsx (no TS toolchain in this workspace).
// Handles: line comments, block comments, '...', "...", `...` with ${} nesting.
const fs = require('fs');
const s = fs.readFileSync(process.argv[2], 'utf8');

let i = 0, line = 1;
let mode = 'code';          // code | line | block | sq | dq | tpl
let modeStart = 1;
const tmplStack = [];       // for ${ } inside template literals
const brackets = [];
const errors = [];
const close = { ')': '(', ']': '[', '}': '{' };
